<template>
  <div class="home-recharge">
    <title-line :title="title" />
    <div class="more-icon" @click="goMore()" />
    <div class="recharge-content">
      <div class="goldIcon" />
      <div class="box">
        <div class="titleLogo">账户充值</div>
        <div class="symbol">
          <span>已支持币种</span>
          <div class="icon-pic" />
        </div>
        <div class="rmbTips">
          <div class="title">想使用人民币充值？</div>
          <div class="tip">主流交易所均支持人民币购买数字货币，点击教程了解 如何使用人民币充值。
            <span @click="goRechargeTutorial()">人民币充值教程</span>
          </div>
        </div>
        <div class="address">
          <span style="color: #87b7ff;">你的 USDT TRC-20充值地址</span><span>，充值完成自动到账</span>
          <div class="content">
            <span>{{ addressValue }}</span>
            <div class="copy-icon" @click="doCopy(addressValue)" />
          </div>
        </div>
        <div class="qrcode">
          <div class="text">
            <div class="warn-icon" />
            <span>此地址只接受 USDT TRC-20 协议充值，存入任何其他货币或协议会造成资金损失并不可追回。最小充值金额为 10 USDT，最大充值金额没有限制，如果存款金额不符合充值要求，则充值不会到账。</span>
          </div>
          <div class="qrIcon">
            <div class="code" style="height:85px;width:85px">
              <div ref="qrcode" style="height:85px;width:85px" class="code-img" />
              <!-- <img class="code-img" src="" alt=""> -->
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import TitleLine from '../modules/TitleLine'
import { getSuppleUrl } from '@/api/user'
import QRCode from 'qrcodejs2'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: '充值',
      addressValue: ''
    }
  },
  async mounted() {
    const res = await getSuppleUrl()
    this.addressValue = res.suppleurl
    var qrcode = new QRCode(this.$refs.qrcode, {
      text: this.addressValue, // xxx为设置要生成二维码的链接
      width: 85,
      height: 85,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.H
    })
  },
  methods: {
    goMore() {
      this.$router.push({ path: '/rechargeRecord' })
    },
    goRechargeTutorial() {
      this.$router.push({ path: '/rechargeTutorial' })
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }

  }

}
</script>
